import urllib.request, json
for code in ['NGDPD','NGDP_RPCH','NGDP','NGDPD_R','NGDP_FD','NGDP_D','NGDP_PC','NGDP','NGDP_R','NGDP_DEF']:
    url=f'https://www.imf.org/external/datamapper/api/v1/{code}/GEO'
    try:
        with urllib.request.urlopen(url, timeout=20) as r:
            data=json.loads(r.read().decode('utf-8'))
            # if data exists, print keys
            print(code, 'keys', list(data.keys()))
            # count years for GEO if present
            if 'values' in data and code in data['values'] and 'GEO' in data['values'][code]:
                years=list(data['values'][code]['GEO'].keys())
                print(' ', code, 'years', years[:3], '...', years[-3:])
    except Exception as e:
        print(code, 'error', e)
PY"}

